tic
clear
% 定义文件路径和工作表名称
filePath = 'D:\OneDrive_Co\Info\marketing\0909A 乳酸 USP_BP #海关数据.xlsx';
sheetName = '2py';
% 读取并清洗数据
[s, t, weights, names] = cleanCustomsDataFromExcel(filePath, sheetName); %[output:9ab7af47]
productName = "Lactic Acid (Pharma Grade)";
time = "2021-2025";
% 构建图
G = digraph(s, t, weights, names);

% Layered 布局
plotCustomGraph(G, 'layered', s, "linear", "", productName, time, "4:3"); %[output:2da5c3a5]
plotCustomGraph(G, 'layered', s, "linear", "", productName, time, "16:9"); %[output:7160c1bd]
plotCustomGraph(G, 'layered', s, "linear", "", productName, time); %[output:20545ea9]
plotCustomGraph(G, 'layered', s, "log10", "", productName, time); %[output:48c1f295]

% % Circle 布局
% plotCustomGraph(G, 'circle', s, "");
% plotCustomGraph(G, 'circle', s, "", "equal");
% plotCustomGraph(G, 'circle', s, "log10");
% plotCustomGraph(G, 'circle', s, "log10", "equal");

% Force 布局
% plotCustomGraph(G, 'force', s, "");
% plotCustomGraph(G, 'force', s, "", "equal");
% plotCustomGraph(G, 'force', s, "log10");
% plotCustomGraph(G, 'force', s, "log10", "equal");


toc %[output:6505d23b]
%%
function h = plotCustomGraph(G, layout, s, datamode, axismode, productName, time, aspectRatio)
% plotCustomGraph 绘制带权重线宽、节点大小和颜色的图（支持节点排序）
%
% 用法:
%   h = plotCustomGraph(G, 'force', s);
%   h = plotCustomGraph(G, 'layered', s);
%   h = plotCustomGraph(G, 'circle', s);
%
% 参数:
%   G           - digraph 对象
%   layout      - 布局方式: 'force' | 'layered' | 'circle'
%   s           - 特殊节点索引（可为空）
%   datamode    - 数据模式: "linear" (默认) | "log10"
%   axismode    - 坐标模式: "tight" (默认) | "equal"
%   productName - 产品名（用于标题）
%   time        - 时间范围（用于标题）

arguments
    G
    layout
    s
    datamode string = "linear"
    axismode string = "tight"
    productName string = ""
    time string = ""
    aspectRatio = "auto" % 新参数，可为"auto"、"4:3"、"16:9"或数值
end

% ---------- 节点强度计算 ----------
n = numnodes(G);
[~, srcIdx] = ismember(G.Edges.EndNodes(:,1), G.Nodes.Name);
[~, tgtIdx] = ismember(G.Edges.EndNodes(:,2), G.Nodes.Name);
allIdx = [srcIdx; tgtIdx];
allWts = [G.Edges.Weight; G.Edges.Weight];
nodeStrength = accumarray(allIdx, allWts, [n, 1]);

% ---------- 节点排序 ----------
[sortedStrength, sortedIdx] = sort(nodeStrength, 'descend');
G_sorted = reordernodes(G, sortedIdx);

% ---------- 边线宽度 ----------
w = G_sorted.Edges.Weight;
if datamode == "log10"
    w = log10(w + eps);
    if max(w) == min(w)
        lineWidth = ones(size(w)) * 5;
    else
        lineWidth = w*1.5;
    end
else
    if max(w) == min(w)
        lineWidth = ones(size(w)) * 5;
    else
        lineWidth = 1 + 9 .* (w - min(w)) ./ (max(w) - min(w));
    end
end

% ---------- 节点大小 ----------
if datamode == "log10"
    nodeStrengthScaled = log10(sortedStrength + eps);
    if max(nodeStrengthScaled) == min(nodeStrengthScaled)
        nodeSize = ones(n, 1) * 8;
    else
        nodeSize = 4 + nodeStrengthScaled * 2.5;
    end
else
    nodeStrengthScaled = sortedStrength;
    if max(nodeStrengthScaled) == min(nodeStrengthScaled)
        nodeSize = ones(n, 1) * 8;
    else
        nodeSize = 4 + 16 .* (nodeStrengthScaled - min(nodeStrengthScaled)) ./ ...
            (max(nodeStrengthScaled) - min(nodeStrengthScaled));
    end
end


% ---------- 节点颜色 ----------
nodeColors = repmat([0 0.447 0.741], n, 1); % 蓝色
orange = [1 0.5 0];
if nargin > 2 && ~isempty(s)
    original_s_names = G.Nodes.Name(unique(s));
    [~, new_s_idx] = ismember(original_s_names, G_sorted.Nodes.Name);
    nodeColors(new_s_idx, :) = repmat(orange, numel(new_s_idx), 1);
    s_sorted = new_s_idx;
else
    s_sorted = [];
end

% ---------- 绘图 ----------
switch lower(layout)
    case 'force'
        h = plot(G_sorted, 'Layout', 'force', ...
            'EdgeLabel', G_sorted.Edges.Weight, ...
            'WeightEffect', 'direct', 'UseGravity', true);
    case 'layered'
        if ~isempty(s_sorted)
            h = plot(G_sorted, 'Layout', 'layered', 'Sources', s_sorted, ...
                'EdgeLabel', G_sorted.Edges.Weight);
        else
            h = plot(G_sorted, 'Layout', 'layered', ...
                'EdgeLabel', G_sorted.Edges.Weight);
        end
    case 'circle'
        h = plot(G_sorted, 'Layout', 'circle', ...
            'EdgeLabel', G_sorted.Edges.Weight);
    otherwise
        error('未知布局: %s', layout);
end

% ---------- 应用属性 ----------
h.LineWidth  = lineWidth;
h.MarkerSize = nodeSize;
h.NodeColor  = nodeColors;

% ---------- 标题 ----------
title(sprintf('International Trading Network of %s, %s', ...
    productName, time), ...
    'FontSize', 14, 'FontWeight', 'bold');

% ---------- 坐标轴与纵横比 ----------
if axismode == "equal"
    axis tight equal;
else
    axis tight;
end

if ~(strcmp(layout,'circle') && axismode=="equal")
    % 非环图/非equal模式下，允许调整纵横比
    if ischar(aspectRatio) || isstring(aspectRatio)
        switch aspectRatio
            case "4:3"
                pbaspect([4 3 1]);
            case "16:9"
                pbaspect([16 9 1]);
            case "auto"
                % 保持默认
            otherwise
                warning("未知纵横比参数: %s，使用默认", aspectRatio);
        end
    elseif isnumeric(aspectRatio) && isscalar(aspectRatio)
        pbaspect([aspectRatio 1 1]); % 直接传宽高比
    end
end

end


%%
function [s, t, weights, names] = cleanCustomsDataFromExcel(filePath, sheetName)

% 读取Excel数据
try
    % data = readtable(filePath, 'Sheet', sheetName);
    data = readtable(filePath, 'Sheet', sheetName, 'VariableNamingRule','preserve');
catch ME
    error('无法读取Excel文件: %s', ME.message);
end
disp(data.Properties.VariableNames)

% 检查必要的列
requiredColumns = {'Exporter', 'EC', 'Importer', 'IC', 'Total Price'};
if ~all(ismember(requiredColumns, data.Properties.VariableNames))
    error('Excel文件中缺少必要的列。需要包含: %s', strjoin(requiredColumns, ', '));
end

data = data(data.("Total Price") > 0, :);
prices = double(data.("Total Price"));
exporters = string(data.("Exporter"));
importers = string(data.("Importer"));
ecs = string(data.("EC"));
ics = string(data.("IC"));


% 映射实体到ID
uniqueEntities = containers.Map('KeyType', 'char', 'ValueType', 'double');
entityNames = {};
nextId = 1;
tradeMap = containers.Map('KeyType', 'char', 'ValueType', 'double');

for i = 1:height(data)
    exporter = strtrim(exporters(i));
    importer = strtrim(importers(i));
    ec = ecs(i);
    ic = ics(i);
    price = prices(i);

    if strlength(exporter)==0 || strlength(importer)==0 || isnan(price)
        continue;
    end

    % 出口商ID
    if ~isKey(uniqueEntities, exporter)
        uniqueEntities(exporter) = nextId;
        entityNames{end+1} = join([ec,exporter],"-");
        nextId = nextId + 1;
    end
    exporterId = uniqueEntities(exporter);

    % 进口商ID
    if ~isKey(uniqueEntities, importer)
        uniqueEntities(importer) = nextId;
        entityNames{end+1} = join([ic,importer],"-");
        nextId = nextId + 1;
    end
    importerId = uniqueEntities(importer);

    % 累加贸易额
    tradeKey = sprintf('%d,%d', exporterId, importerId);
    if isKey(tradeMap, tradeKey)
        tradeMap(tradeKey) = tradeMap(tradeKey) + price;
    else
        tradeMap(tradeKey) = price;
    end
end

% 输出数组
keys = tradeMap.keys;
s = zeros(length(keys), 1);
t = zeros(length(keys), 1);
weights = zeros(length(keys), 1);

for i = 1:length(keys)
    parts = strsplit(keys{i}, ',');
    s(i) = str2double(parts{1});
    t(i) = str2double(parts{2});
    weights(i) = round(tradeMap(keys{i}));
end

names = cellfun(@char, entityNames, 'UniformOutput', false);

% 摘要
fprintf('数据处理完成:\n');
fprintf('- 处理记录数: %d\n', height(data));
fprintf('- 有效贸易关系: %d\n', length(s));
fprintf('- 唯一实体数: %d\n', length(names));
fprintf('- 总贸易额: %.2f\n', sum(weights));


end


